@Component("aPU-entity-projector")
public class APUEntityProjector implements EntityProjector<APU>{
		
	// core constructor
	public APUEntityProjector(ProjectorRegistry registry,
										APURepository repository ) {
        this.registry 	= registry;
		this.repository = repository;
    }

	@Override
	public Class<APU> getEntityClass() {
		return APU.class;
	}

    /*
	 * Insert a APU
	 * 
     * @param	entity APU
     */
    public APU create( APU entity) {
	    LOGGER.info("creating " + entity.toString() );
	   
    	// ------------------------------------------
    	// persist a new one
    	// ------------------------------------------ 
	    return repository.save(entity);
        
    }

	/*
	 * Update a APU
	 * 
     * @param	entity APU
     */
    public APU update( APU entity) {
	    LOGGER.info("updating " + entity.toString() );

	    // ------------------------------------------
    	// save with an existing instance
    	// ------------------------------------------ 
		return repository.save(entity);

    }
    
	/*
	 * Delete a APU
	 * 
     * @param	id		UUID
     */
    public APU delete( UUID id ) {
	    LOGGER.info("deleting " + id.toString() );

    	// ------------------------------------------
    	// locate the entity by the provided id
    	// ------------------------------------------
	    APU entity = repository.findById(id).get();
	    
    	// ------------------------------------------
    	// delete what is discovered 
    	// ------------------------------------------
    	repository.delete( entity );
    	
    	return entity;
    }    

    /*
     * Assign a Supplier
     * 
     * @param	parentId	UUID
     * @param	assignment 	Supplier 
     * @return	APU
     */
    public APU assignSupplier( UUID parentId, Supplier assignment ) {
	    LOGGER.info("assigning Supplier as " + assignment.toString() );

	    APU parentEntity = repository.findById( parentId ).get();
	    assignment = registry.project( Supplier.class, assignment.getSupplierId());

	    // ------------------------------------------
		// assign the Supplier to the parent entity
		// ------------------------------------------ 
	    parentEntity.setSupplier( assignment );

	    // ------------------------------------------
    	// save the parent entity
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

	/*
	 * Unassign the Supplier
	 * 
	 * @param	parentId		UUID
	 * @return	APU
	 */
	public APU unAssignSupplier( UUID parentId ) {
		APU parentEntity = repository.findById(parentId).get();

		LOGGER.info("unAssigning Supplier on " + parentEntity.toString() );
		
	    // ------------------------------------------
		// null out the Supplier on the parent entithy
		// ------------------------------------------     
	    parentEntity.setSupplier(null);

	    // ------------------------------------------
		// save the parent entity
		// ------------------------------------------ 
	    repository.save(parentEntity);
    
	    return parentEntity;
	}


    /*
     * Add to the Variants
     * 
     * @param	parentID	UUID
     * @param	addTo		childType
     * @return	APU
     */
    public APU addToVariants( UUID parentId, AircraftVariant addTo ) {
	    LOGGER.info("handling AssignVariantsToAPUEvent - " );
	    
	    APU parentEntity = repository.findById(parentId).get();
	    AircraftVariant child = registry.project( AircraftVariant.class, addTo.getAircraftVariantId());
	    
	    parentEntity.getVariants().add( child );

	    // ------------------------------------------
    	// save 
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

    /*
     * Remove from the Variants
     * 
     * @param	parentID	UUID
     * @param	removeFrom	childType
     * @return	APU
     */
	public APU removeFromVariants( UUID parentId, AircraftVariant removeFrom ) {
	    LOGGER.info("handling RemoveVariantsFromAPUEvent " );
	
	    APU parentEntity = repository.findById(parentId).get();
	    AircraftVariant child = registry.project( AircraftVariant.class, removeFrom.getAircraftVariantId());
	    
	    parentEntity.getVariants().remove( child );
	
	    // ------------------------------------------
		// save
		// ------------------------------------------ 
	    update(parentEntity);
	    
	    return parentEntity;
	}



    /**
     * Method to retrieve the APU via an FindAPUQuery
     * @return 	query	FindAPUQuery
     */
    @SuppressWarnings("unused")
    public APU find( UUID id ) {
    	LOGGER.info("handling find using " + id.toString() );
    	try {
    		return repository.findById(id).get();
    	}
    	catch( IllegalArgumentException exc ) {
    		LOGGER.warn( "Failed to find a APU - {0}", exc.getMessage() );
    	}
    	return null;
    }
    
    /**
     * Method to retrieve a collection of all APUs
     *
     * @param	query	FindAllAPUQuery 
     * @return 	List<APU> 
     */
    @SuppressWarnings("unused")
    public List<APU> findAll( FindAllAPUQuery query ) {
    	LOGGER.info("handling findAll using " + query.toString() );
    	try {
    		return repository.findAll();
    	}
    	catch( IllegalArgumentException exc ) {
    		LOGGER.warn( "Failed to find all APU - {0}", exc.getMessage() );
    	}
    	return null;
    }


    //--------------------------------------------------
    // attributes
    // --------------------------------------------------
	@Autowired
    protected final APURepository repository;
	protected final ProjectorRegistry registry;


    private static final Logger LOGGER 	= LoggerFactory.getLogger(APUEntityProjector.class.getName());

}
